1\u0947\u091f\u093e\u0938\u0947\u091f \u0921\u093f\u0938\u094d\u0915 \u092a\u0930 \u092a\u094d\u0930\u0940-\u0907\u0902\u0938\u094d\u091f\u0949\u0932\u094d\u0921 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964", "uncertainties": ["\u092e\u0942\u0932 \u0905\u0927\u094d\u092f\u092f\u0928 \u092e\u0947\u0902 \u0915\u094c\u0928-\u0915\u094c\u0928 \u0938\u0947 \u0935\u093f\u0936\u093f\u0937\u094d\u091f \u092a\u094d\u0930\u094b\u091f\u0940\u0928/\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u0938\u093f\u0938\u094d\u091f\u092e\u094d\u0938 (\u0909\u0926\u093e. Chignolin, BBA, Villin) \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u093f\u0924 \u0915\u093f\u090f \u0917\u090f \u0939\u0948\u0902? (Setup Topics: setup_2, setup_13, setup_14)", "TICA \u0915\u0902\u092a\u094b\u0928\u0947\u0902\u091f\u094d\u0938 \u0915\u0947 \u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0915\u0947 \u0932\u093f\u090f \u0915\u094c\u0928 \u0938\u0947 \u0907\u0928\u092a\u0941\u091f \u092b\u0940\u091a\u0930\u094d\u0938 (pairwise heavy-atom distances \u092f\u093e torsion angles) \u0914\u0930 \u0935\u093f\u0936\u093f\u0937\u094d\u091f \u0932\u0948\u0917-\u091f\u093e\u0907\u092e ($\\tau$) \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u090f \u0917\u090f \u0939\u0948\u0902?", "\u092b\u0949\u0930\u0935\u0930\u094d\u0921 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0949\u0921\u0932 \u0915\u093e \u092a\u094d\u0930\u0947\u0921\u093f\u0915\u094d\u0936\u0928 \u091f\u093e\u0907\u092e-\u0938\u094d\u091f\u0947\u092a ($\\Delta t$) \u0915\u094d\u092f\u093e \u0939\u0948 \u0914\u0930 \u0915\u094d\u092f\u093e \u092f\u0939 \u0915\u0902\u0921\u0940\u0936\u0928\u0932 \u091c\u0928\u0930\u0947\u091f\u0930 \u0939\u0948 \u092f\u093e \u0905\u0928\u0915\u0902\u0921\u0940\u0936\u0928\u0932?"], "answer": "\u0928\u092e\u0938\u094d\u0924\u0947\u0964 \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u0915\u0947 \u0928\u093f\u0930\u0940\u0915\u094d\u0937\u0923 \u0915\u0947 \u092c\u093e\u0926, \u092b\u0949\u0930\u0935\u0930\u094d\u0921 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0949\u0921\u0932 \u0914\u0930 \u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 MD (\u092e\u0949\u0932\u093f\u0915\u094d\u092f\u0942\u0932\u0930 \u0921\u093e\u092f\u0928\u0947\u092e\u093f\u0915\u094d\u0938) \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0915\u0947 \u092c\u0940\u091a \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928\u0932 \u0938\u092e\u093e\u0928\u0924\u093e \u0915\u093e \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u092a\u094d\u0930\u092f\u094b\u0917 \u0921\u093f\u091c\u093e\u0907\u0928 (Proposed Approach) \u0928\u0940\u091a\u0947 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0939\u0948:\n\n### 1. \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 (Proposed Approach)\n\n**\u0915. \u0921\u0947\u091f\u093e \u0914\u0930 \u091f\u094d\u0930\u0948\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u091c\u0928\u0930\u0947\u0936\u0928 (Trajectory Sampling & Alignment):**\n- **\u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 (GT) \u0921\u0947\u091f\u093e:** \u092e\u093e\u0928\u0915 \u0932\u0902\u092c\u0947 \u0938\u092e\u092f-\u092a\u0948\u092e\u093e\u0928\u0947 (microsecond-scale) \u0935\u093e\u0932\u0947 MD \u0921\u0947\u091f\u093e\u0938\u0947\u091f (\u091c\u0948\u0938\u0947 DESRES \u092b\u093e\u0938\u094d\u091f-\u092b\u094b\u0932\u094d\u0921\u093f\u0902\u0917 \u092a\u094d\u0930\u094b\u091f\u0940\u0928\u094d\u0938, \u0909\u0926\u093e. Chignolin, Trp-cage \u0906\u0926\u093f) \u0938\u0947 \u0938\u0928\u094d\u0926\u0930\u094d\u092d \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0932\u0940 \u091c\u093e\u090f\u0917\u0940\u0964\n- **\u092b\u0949\u0930\u0935\u0930\u094d\u0921 \u092e\u0949\u0921\u0932 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917:** \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0949\u0921\u0932 \u0926\u094d\u0935\u093e\u0930\u093e \u0909\u0938\u0940 \u0938\u092e\u093e\u0928 \u091f\u093e\u0907\u092e-\u0938\u094d\u091f\u0947\u092a / \u0905\u0902\u0924\u0930\u093e\u0932 ($\\Delta t$) \u092a\u0930 \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u0906\u0930\u0902\u092d\u093f\u0915 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 (folded, unfolded, metastable states) \u0938\u0947 \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u0938\u0902\u0916\u094d\u092f\u093e \u092e\u0947\u0902 \u0932\u0902\u092c\u0940 \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c \u0938\u0948\u0902\u092a\u0932 \u0915\u0940 \u091c\u093e\u090f\u0902\u0917\u0940 \u0924\u093e\u0915\u093f \u0915\u0941\u0932 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 \u0938\u092e\u092f \u0924\u0941\u0932\u0928\u0940\u092f \u0939\u094b\u0964\n\n**\u0916. \u092a\u094d\u0930\u092e\u0941\u0916 \u0915\u0932\u0947\u0915\u094d\u091f\u093f\u0935 \u0935\u0948\u0930\u093f\u090f\u092c\u0932\u094d\u0938 (CVs) \u0915\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923:**\n1. **Backbone Torsions ($\\phi, \\psi$):**\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0905\u0935\u0936\u0947\u0937 (residue) \u0915\u0947 \u0932\u093f\u090f \u0930\u093e\u092e\u093e\u091a\u0902\u0926\u094d\u0930\u0928 \u0915\u094b\u0923\u094b\u0902 ($\\phi, \\psi$) \u0915\u093e 2D \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 \u0928\u093f\u0915\u093e\u0932\u0928\u093e\u0964\n   - GT \u0914\u0930 \u092e\u0949\u0921\u0932 \u091c\u0928\u0930\u0947\u091f\u0947\u0921 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 \u0915\u0947 \u092c\u0940\u091a Jensen-Shannon Divergence (JSD) \u0914\u0930 Wasserstein distance \u0915\u0940 \u0917\u0923\u0928\u093e \u0915\u0930\u0928\u093e\u0964\n2. **Sidechain Torsions ($\\chi_1, \\chi_2, \\dots$):**\n   - \u0930\u094b\u091f\u093e\u092e\u0930 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 (rotameric states) \u0915\u0947 \u0938\u0930\u094d\u0915\u0941\u0932\u0930 \u090f\u0902\u0917\u0932 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 \u0915\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0914\u0930 1D JSD \u0915\u0947 \u092e\u093e\u0927\u094d\u092f\u092e \u0938\u0947 \u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u092b\u094d\u0932\u0947\u0915\u094d\u0938\u093f\u092c\u093f\u0932\u093f\u091f\u0940 \u0915\u093e \u092e\u093f\u0932\u093e\u0928\u0964\n3. **Top TICA Components (TICA 1, TICA 2):**\n   - GT MD \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u092a\u0930 \u0909\u092a\u092f\u0941\u0915\u094d\u0924 \u0932\u0948\u0917-\u091f\u093e\u0907\u092e ($\\tau$) \u092a\u0930 TICA (Time-lagged Independent Component Analysis) \u092e\u0949\u0921\u0932 \u0915\u094b \u092b\u093f\u091f \u0915\u0930\u0928\u093e (\u092c\u0948\u0915\u092c\u094b\u0928/\u0939\u0948\u0935\u0940-\u090f\u091f\u092e \u0926\u0942\u0930\u093f\u092f\u094b\u0902 \u092f\u093e \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938 \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930)\u0964\n   - \u0926\u094b\u0928\u094b\u0902 (GT \u0914\u0930 \u092e\u0949\u0921\u0932) \u0915\u0940 \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c \u0915\u094b \u0909\u0938\u0940 \u0938\u093e\u091d\u093e TICA \u0938\u092c\u0938\u094d\u092a\u0947\u0938 \u092e\u0947\u0902 \u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u091f \u0915\u0930\u0928\u093e\u0964\n   - 2D \u092b\u094d\u0930\u0940 \u090f\u0928\u0930\u094d\u091c\u0940 \u0932\u0948\u0902\u0921\u0938\u094d\u0915\u0947\u092a ($F = -k_B T \\ln P$) \u0914\u0930 2D \u092a\u094d\u0930\u094b\u092c\u0947\u092c\u093f\u0932\u093f\u091f\u0940 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 \u0915\u093e JSD / \u0913\u0935\u0930\u0932\u0948\u092a \u092e\u093e\u092a\u0928\u093e\u0964\n4. **\u092a\u0942\u0930\u0915 \u092e\u0948\u0915\u094d\u0930\u094b\u0938\u094d\u0915\u094b\u092a\u093f\u0915 CVs:** RMSD, \u0930\u0947\u0921\u093f\u092f\u0938 \u0911\u092b \u0917\u093e\u0907\u0930\u0947\u0936\u0928 ($R_g$), \u0914\u0930 \u0907\u0902\u091f\u0930-\u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942 \u0915\u093e\u0902\u091f\u0947\u0915\u094d\u091f \u092e\u0948\u092a\u094d\u0938\u0964\n\n**\u0917. \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0938 \u0914\u0930 \u0938\u094d\u091f\u0948\u091f\u093f\u0938\u094d\u091f\u093f\u0915\u0932 \u0935\u0948\u0932\u093f\u0921\u0947\u0936\u0928:**\n- **Positive Control:** \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 MD \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0938\u094d\u092a\u094d\u0932\u093f\u091f (GT split A vs GT split B) \u0924\u093e\u0915\u093f \u092a\u0930\u093f\u092e\u093f\u0924 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 (finite sampling noise) \u0915\u093e \u092c\u0947\u0938\u0932\u093e\u0907\u0928 \u0921\u093f\u0938\u094d\u091f\u0948\u0902\u0938 \u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0939\u094b \u0938\u0915\u0947\u0964\n- **Negative Control:** \u0905\u0928\u091f\u094d\u0930\u0947\u0902\u0921/\u0930\u0948\u0902\u0921\u092e \u091c\u0928\u0930\u0947\u091f\u0930 \u092f\u093e \u0938\u094d\u0915\u094d\u0930\u0948\u092e\u094d\u092c\u0932\u094d\u0921 \u0938\u094d\u091f\u0947\u091f\u094d\u0938\u0964\n\n---\n\u0915\u0943\u092a\u092f\u093e \u0907\u0938 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0915\u0940 \u0938\u092e\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0902\u0964 \u0906\u092a\u0915\u0947 \u0905\u0928\u0941\u092e\u094b\u0926\u0928 \u0915\u0947 \u092a\u0936\u094d\u091a\u093e\u0924 \u0935\u093f\u0938\u094d\u0924\u0943\u0924 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 (complete experiment design) \u0924\u0948\u092f\u093e\u0930 \u0915\u093f\u092f\u