ns) \u0914\u0930 \u092e\u0947\u091f\u093e\u0938\u094d\u091f\u0947\u092c\u0932 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 \u0915\u0947 \u092c\u0940\u091a \u0927\u0940\u092e\u0940 \u0917\u0924\u093f (slow kinetics) \u0936\u093e\u092e\u093f\u0932 \u0939\u094b\u0924\u0940 \u0939\u0948\u0902\u0964\n- \u0915\u0947\u0935\u0932 \u090f\u0915\u0932 3D \u0938\u0902\u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u0924\u094d\u0930\u0941\u091f\u093f (\u091c\u0948\u0938\u0947 RMSD) \u091c\u093e\u0902\u091a\u0928\u093e \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948; \u090f\u0915 \u092d\u094c\u0924\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u0935\u0948\u0927 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u092e\u0949\u0921\u0932 \u0915\u094b \u0938\u0902\u0924\u0941\u0932\u0928 \u090f\u0902\u0938\u0947\u0902\u092c\u0932 (equilibrium ensemble), \u092b\u094d\u0930\u0940 \u090f\u0928\u0930\u094d\u091c\u0940 \u0932\u0948\u0902\u0921\u0938\u094d\u0915\u0947\u092a \u0914\u0930 \u0927\u0940\u092e\u0940 \u0917\u0924\u093f\u0915 \u0935\u093f\u0927\u093e\u0913\u0902 (slowest dynamical modes) \u0915\u094b \u0938\u0939\u0940 \u0922\u0902\u0917 \u0938\u0947 \u092a\u0941\u0928\u0930\u0941\u0924\u094d\u092a\u093e\u0926\u093f\u0924 \u0915\u0930\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n\n---\n\n### 2. \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0914\u0930 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u0938\u0947\u091f\u0905\u092a (Datasets & Sampling Protocol)\n\n1. **\u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 (GT) MD \u0921\u0947\u091f\u093e:**\n   - **\u0938\u093f\u0938\u094d\u091f\u092e:** \u0928\u094d\u092f\u0942\u091f\u094d\u0930\u0932 \u092f\u093e \u0915\u0948\u092a\u094d\u0921 \u091f\u0947\u091f\u094d\u0930\u093e\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921\u094d\u0938 (\u091c\u0948\u0938\u0947 Ace-XXXX-Nme) \u0915\u093e \u0911\u0932-\u090f\u091f\u092e \u090f\u0915\u094d\u0938\u092a\u094d\u0932\u093f\u0938\u093f\u091f \u0938\u0949\u0932\u094d\u0935\u0947\u0902\u091f MD \u0921\u0947\u091f\u093e (\u0909\u0926\u093e. AMBER ff14SB / CHARMM36m \u092b\u093c\u094b\u0930\u094d\u0938 \u092b\u0940\u0932\u094d\u0921 \u0915\u0947 \u0924\u0939\u0924)\u0964\n   - **\u0921\u0947\u091f\u093e \u0905\u0935\u0927\u093f \u0935 \u0905\u0902\u0924\u0930\u093e\u0932:** \u092e\u0932\u094d\u091f\u0940-\u092e\u093e\u0907\u0915\u094d\u0930\u094b\u0938\u0947\u0915\u0902\u0921 \u0932\u0902\u092c\u0940 \u0907\u0915\u094d\u0935\u093f\u0932\u093f\u092c\u094d\u0930\u093f\u092f\u092e \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c, \u091c\u093f\u0928\u094d\u0939\u0947\u0902 \u090f\u0915 \u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 \u0905\u0902\u0924\u0930\u093e\u0932 ($\\Delta t$, \u0909\u0926\u093e. 10 ps \u092f\u093e 50 ps) \u092a\u0930 \u0938\u094d\u091f\u094d\u0930\u093e\u0907\u0921/\u0938\u0947\u0935 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964\n   - **\u0921\u0947\u091f\u093e \u0935\u093f\u092d\u093e\u091c\u0928:** \u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 \u0921\u0947\u091f\u093e \u0915\u094b \u0926\u094b \u0938\u092e\u093e\u0928, \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u092d\u093e\u0917\u094b\u0902 (GT-Split-1 \u0914\u0930 GT-Split-2) \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e (\u092a\u0949\u091c\u093f\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 \u0939\u0947\u0924\u0941)\u0964\n\n2. **\u092b\u0949\u0930\u0935\u0930\u094d\u0921 \u092e\u0949\u0921\u0932 \u091c\u0928\u0930\u0947\u0936\u0928 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 (Model Rollout):**\n   - **\u0906\u0930\u0902\u092d\u093f\u0915 \u0938\u0902\u0930\u091a\u0928\u093e\u090f\u0902 (Initialization):** \u092e\u0949\u0921\u0932 \u0915\u0940 \u0911\u091f\u094b\u0930\u093f\u0917\u094d\u0930\u0947\u0938\u093f\u0935 \u0930\u094b\u0932\u0906\u0909\u091f\u094d\u0938 \u0915\u094b GT \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0938\u0947 \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u093f\u0924 \u0935\u093f\u092d\u093f\u0928\u094d\u0928 \u092e\u0947\u091f\u093e\u0938\u094d\u091f\u0947\u092c\u0932 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 (\u0905\u0932\u0917-\u0905\u0932\u0917 $\\alpha, \\beta$, \u0914\u0930 \u0905\u0928\u092b\u094b\u0932\u094d\u0921\u0947\u0921 \u0915\u0928\u094d\u092b\u0930\u094d\u092e\u0947\u0936\u0928\u094d\u0938) \u0938\u0947 \u0936\u0941\u0930\u0942 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n   - **\u0915\u0941\u0932 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 \u0932\u0902\u092c\u093e\u0908:** \u0915\u0941\u0932 \u092b\u094d\u0930\u0947\u092e \u0938\u0902\u0916\u094d\u092f\u093e \u0914\u0930 \u0915\u0941\u0932 \u0938\u093f\u092e\u094d\u092f\u0941\u0932\u0947\u091f\u0947\u0921 \u0938\u092e\u092f \u0915\u094b \u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0915\u0947 \u092c\u0930\u093e\u092c\u0930 \u0930\u0916\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n   - **\u092d\u094c\u0924\u093f\u0915 \u0938\u094d\u0925\u093f\u0930\u0924\u093e \u091c\u093e\u0902\u091a:** \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u091a\u0930\u0923 \u092a\u0930 \u090f\u091f\u0949\u092e\u093f\u0915 \u0915\u094d\u0932\u0948\u0936 (interatomic steric clashes) \u0914\u0930 \u0905\u092e\u093e\u0928\u094d\u092f \u092c\u0949\u0928\u094d\u0921 \u091c\u094d\u092f\u094b\u092e\u0947\u091f\u094d\u0930\u0940 \u0915\u093e \u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u0938\u0924\u094d\u092f\u093e\u092a\u0928\u0964\n\n---\n\n### 3. \u092a\u094d\u0930\u092e\u0941\u0916 \u0915\u0932\u0947\u0915\u094d\u091f\u093f\u0935 \u0935\u0948\u0930\u093f\u090f\u092c\u0932\u094d\u0938 (Key Collective Variables)\n\n1. **\u092c\u0948\u0915\u092c\u094b\u0928 \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938 (Backbone Torsions - $\\phi, \\psi, \\omega$):**\n   - \u091f\u0947\u091f\u094d\u0930\u093e\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u0915\u0947 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0906\u0902\u0924\u0930\u093f\u0915 \u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942 \u0915\u0947 \u0932\u093f\u090f \u092e\u0941\u0916\u094d\u092f-\u091a\u0947\u0928 \u0921\u093e\u092f\u0939\u0947\u0921\u094d\u0930\u0932 \u090f\u0902\u0917\u0932\u094d\u0938 $(\\phi_i, \\psi_i)$ \u0914\u0930 \u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u092c\u0949\u0928\u094d\u0921 \u092a\u094d\u0932\u0948\u0928\u0948\u0930\u093f\u091f\u0940 $(\\omega_i)$ \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n   - 2D \u0930\u093e\u092e\u093e\u091a\u0902\u0926\u094d\u0930\u0928 \u092a\u094d\u0930\u094b\u092c\u0947\u092c\u093f\u0932\u093f\u091f\u0940 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 $P(\\phi_i, \\psi_i)$ \u0915\u093e \u0928\u093f\u0930\u094d\u092e\u093e\u0923\u0964\n2. **\u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938 (Sidechain Torsions - $\\chi_1, \\chi_2, \\dots$):**\n   - \u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u0935\u093e\u0932\u0947 \u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942\u091c \u0915\u0947 \u0932\u093f\u090f \u0930\u094b\u091f\u093e\u092e\u0930 \u090f\u0902\u0917\u0932\u094d\u0938 ($\\chi_1, \\chi_2$) \u0915\u093e \u0938\u0930\u094d\u0915\u0941\u0932\u0930 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928\u0964\n   - \u0930\u094b\u091f\u093e\u092e\u0930 \u0905\u0935\u0938\u094d\u0925\u093e\u0913\u0902 (gauche+, trans, gauche-) \u0915\u0947 \u092a\u0949\u092a\u0941\u0932\u0947\u0936\u0928 \u0905\u0928\u0941\u092a\u093e\u0924 \u0915\u093e \u092e\u093e\u092a\u0928\u0964\n3. **\u091f\u0949\u092a TICA \u0915\u0902\u092a\u094b\u0928\u0947\u0902\u091f\u094d\u0938 (Top TICA Components):**\n   - **\u092b\u0940\u091a\u0930 \u0935\u0947\u0915\u094d\u091f\u0930\u094d\u0938:** \u092a\u0940\u0930\u093f\u092f\u094b\u0921\u093f\u0915 \u092c\u093e\u0909\u0902\u0921\u094d\u0930\u0940 \u0921\u093f\u0938\u094d\u0915\u0902\u091f\u0940\u0928\u094d\u092f\u0942\u091f\u0940 \u0938\u0947 \u092c\u091a\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u092d\u0940 \u092c\u0948\u0915\u092c\u094b\u0928 \u0935 \u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938 \u0915\u0947 \u0938\u093e\u0907\u0928/\u0915\u094b\u0938\u093e\u0907\u0928 \u091f\u094d\u0930\u093e\u0902\u0938\u092b\u0949\u0930\u094d\u092e\u094d\u0938 $(\\sin \\theta, \\cos \\theta)$ \u0905\u0925\u0935\u093e \u0938\u092d\u0940 \u0928\u0949\u0928-\u0932\u094b\u0915\u0932 \u0939\u0947\u0935\u0940-\u090f\u091f\u092e \u092a\u0947\u092f\u0930\u0935\u093e\u0907\u091c \u0926\u0942\u0930\u093f\u092f\u094b\u0902 ($C_\\alpha, C_\\beta, \\dots$) \u0915\u093e \u0909\u092a\u092f\u094b\u0917\u0964\n   - **TICA \u092e\u0949\u0921\u0932 \u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917:** \u0915\u0947\u0935\u0932 GT \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u092a\u0930 \u091f\u093e\u0907\u092e-\u0932\u0948\u0917\u094d\u0921 \u0915\u094b\u0935\u0948\u0930\u093f\u092f\u0902\u0938 \u092e\u0948\u091f\u094d\u0930\u093f\u0915\u094d\u0938 $C(0)$ \u0914\u0930 $C(\\tau)$ \u0915\u094b \u092b\u093f\u091f \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e (\u091c\u0939\u093e\u0902 \u0932\u0948\u0917 \u091f\u093e\u0907\u092e $\\tau$ \u0915\u093e \u091a\u092f\u0928 \u0907\u092e\u094d\u092a\u094d\u0932\u093e\u0907\u0921 \u091f\u093e\u0907\u092e\u0938\u094d\u0915\u0947\u0932 \u0915\u0947 \u0938\u094d\u0925\u093f\u0930 \u0939\u094b\u0928\u0947 \u092a\u0930 \u0906\u0927\u093e\u0930\u093f\u0924 \u0939\u094b\u0917\u093e)\u0964\n   - **\u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u0936\u0928:** GT \u0914\u0930 \u092e\u0949\u0921\u0932-\u091c\u0928\u0930\u0947\u091f\u0947\u0921 \u0926\u094b\u0928\u094b\u0902 \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c \u0915\u094b \u0907\u0928\u094d\u0939\u0940\u0902 \u0936\u0940\u0930\u094d\u0937 \u0926\u094b \u0906\u0907\u0917\u0947\u0928\u0935\u0947\u0915\u094d\u091f\u0930\u094d\u0938 (TIC 1 \u0914\u0930 TIC 2) \u092a\u0930 \u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u091f \u0915\u0930\u0915\u0947 2D \u092b\u094d\u0930\u0940-\u090f\u0928\u0930\u094d\u091c\u0940 \u0932\u0948\u0902\u0921\u0938\u094d\u0915\u0947\u092a ($F(x) = -k_B T \\ln P(x)$) \u0924\u0948\u092f\u093e\u0930 \u0915\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964\n\n---\n\n### 4. \u092e\u093e\u0924\u094d\u0930\u093e\u0924\u094d\u092e\u0915 \u0938\u092e\u093e\u0928\u0924\u093e \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 (Quantitative Similarity Metrics)\n\n1. **\u091c\u0947\u0928\u094d\u0938\u0947\u0928-\u0936\u0948\u0928\u0928 \u0921\u093e\u0907\u0935\u0930\u094d\u091c\u0947\u0902\u0938 (Jensen-Shannon Divergence - JSD):**\n   - $\\text{JSD}(P \\parallel Q) = \\frac{1}{2} D_{KL}(P \\parallel M) + \\frac{1}{2} D_{KL}(Q \\parallel M)$, \u091c\u0939\u093e\u0902 $M = \\frac{1}{2}(P + Q)$\u0964\n   - \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0930\u0947\u091c\u093f\u0921\u094d\u092f\u0942 \u0915\u0947 2D \u0930\u093e\u092e\u093e\u091a\u0902\u0926\u094d\u0930\u0928 \u0917\u094d\u0930\u093f\u0921 \u0914\u0930 1D \u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u0938\u0930\u094d\u0915\u0941\u0932\u0930 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928 \u092a\u0930 JSD \u0915\u0940 \u0917\u0923\u0928\u093e (\u0930\u0947\u0902\u091c: [0, 1] \u092c\u093f\u091f\u094d\u0938)\u0964\n   - \u0936\u0940\u0930\u094d\u0937 \u0926\u094b TICA \u0915\u0902\u092a\u094b\u0928\u0947\u0902\u091f\u094d\u0938 \u0915\u0947 2D \u092b\u094d\u0930\u0940 \u090f\u0928\u0930\u094d\u091c\u0940 \u0917\u094d\u0930\u093f\u0921 \u092a\u0930 JSD \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n2. **\u0935\u093e\u0938\u0930\u0938\u094d\u091f\u0940\u0928 \u0926\u0942\u0930\u0940 (Wasserstein / Earth Mover's Distance):**\n   - \u091a\u0915\u094d\u0930\u0940\u092f \u090f\u0902\u0917\u0932\u094d\u0938 \u0915\u0947 \u0932\u093f\u090f \u0938\u0930\u094d\u0915\u0941\u0932\u0930 1D \u0935\u093e\u0938\u0930\u0938\u094d\u091f\u0940\u0928 \u0926\u0942\u0930\u0940 ($W_1$ distance)\u0964\n   - TICA \u0938\u094d\u092a\u0947\u0938 $(TIC_1, TIC_2)$ \u092e\u0947\u0902 2D \u0935\u093e\u0938\u0930\u0938\u094d\u091f\u0940\u0928 \u0926\u0942\u0930\u0940, \u091c\u094b \u0915\u0947\u0935\u0932 \u092c\u093f\u0928\u093f\u0902\u0917 \u092a\u0930 \u0928\u093f\u0930\u094d\u092d\u0930 \u0928 \u0930\u0939\u0915\u0930 \u0915\u0928\u094d\u092b\u0930\u094d\u092e\u0947\u0936\u0928\u0932 \u0921\u0947\u0902\u0938\u093f\u091f\u0940 \u0936\u093f\u092b\u094d\u091f \u0915\u094b \u092e\u093e\u092a\u0924\u0940 \u0939\u0948\u0964\n3. **\u092b\u094d\u0930\u0940 \u090f\u0928\u0930\u094d\u091c\u0940 \u0932\u0948\u0902\u0921\u0938\u094d\u0915\u0947\u092a \u0913\u0935\u0930\u0932\u0948\u092a \u0914\u0930 \u092c\u0948\u0930\u093f\u092f\u0930 \u0939\u093e\u0907\u091f:**\n   - \u092e\u0947\u091f\u093e\u0938\u094d\u091f\u0947\u092c\u0932 \u092c\u0947\u0938\u093f\u0928\u094b\u0902 (local minima) \u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f, \u0909\u0928\u0915\u0940 \u0917\u0939\u0930\u093e\u0908 \u0914\u0930 \u0909\u0928\u0915\u0947 \u092e\u0927\u094d\u092f \u0938\u094d\u0925\u093f\u0924 \u091f\u094d\u0930\u093e\u0902\u091c\u093c\u093f\u0936\u0928 \u0938\u094d\u091f\u0947\u091f \u092c\u0948\u0930\u093f\u092f\u0930\u094d\u0938 ($\\Delta \\Delta F^\\ddagger$) \u0915\u093e \u0930\u0942\u091f \u092e\u0940\u0928 \u0938\u094d\u0915\u094d\u0935\u0947\u0930 \u090f\u0930\u0930 (RMSE)\u0964\n4. **\u0907\u092e\u094d\u092a\u094d\u0932\u093e\u0907\u0921 \u091f\u093e\u0907\u092e\u0938\u094d\u0915\u0947\u0932\u094d\u0938 \u0914\u0930 \u0915\u093e\u0907\u0928\u0947\u091f\u093f\u0915\u094d\u0938 (MSM Validation):**\n   - \u0926\u094b\u0928\u094b\u0902 \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c \u092a\u0930 \u090f\u0915 \u0938\u092e\u093e\u0928 \u0915\u094d\u0932\u0938\u094d\u091f\u0930\u093f\u0902\u0917 \u0932\u093e\u0917\u0942 \u0915\u0930\u0915\u0947 \u092e\u093e\u0930\u094d\u0915\u094b\u0935 \u0938\u094d\u091f\u0947\u091f \u092e\u0949\u0921\u0932 (MSM) \u0915\u093e \u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0924\u0925\u093e \u0927\u0940\u092e\u0940 \u0917\u0924\u093f\u0915 \u0935\u093f\u0927\u093e\u0913\u0902 \u0915\u0947 \u0930\u093f\u0932\u0948\u0915\u094d\u0938\u0947\u0936\u0928 \u091f\u093e\u0907\u092e\u0938\u094d\u0915\u0947\u0932 ($\\tau_i = -\\tau / \\ln |\\lambda_i|$) \u0915\u0940 \u0924\u0941\u0932\u0928\u093e\u0964\n\n---\n\n### 5. \u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915 \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0938 (Experimental Controls)\n\n1. **\u092a\u0949\u091c\u093f\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 (Positive Control - Noise Floor):**\n   - \u0926\u094b \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0938\u092e\u0924\u0941\u0932\u094d\u092f \u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 \u0938\u092c-\u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940\u091c\u093c (GT-Split-1 \u092c\u0928\u093e\u092e GT-Split-2) \u0915\u0947 \u092c\u0940\u091a JSD \u0914\u0930 \u0935\u093e\u0938\u0930\u0938\u094d\u091f\u0940\u0928 \u0926\u0942\u0930\u0940 \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n   - \u092f\u0939 \u092a\u0930\u093f\u092e\u093f\u0924 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 (finite sampling error) \u0915\u0947 \u0915\u093e\u0930\u0923 \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0939\u094b\u0928\u0947 \u0935\u093e\u0932\u0940 \u0928\u094d\u092f\u0942\u0928\u0924\u092e \u0938\u094d\u0935\u093e\u092d\u093e\u0935\u093f\u0915 \u0935\u093f\u091a\u0932\u0928 \u0938\u0940\u092e\u093e (empirical lower bound) \u0915\u094b \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948\u0964 \u0938\u092b\u0932 \u092e\u0949\u0921\u0932 \u0915\u093e \u0935\u093f\u091a\u0932\u0928 \u0907\u0938 \u0938\u0940\u092e\u093e \u0915\u0947 \u0928\u093f\u0915\u091f \u0939\u094b\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964\n2. **\u0928\u0947\u0917\u0947\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 1 (Scrambled Temporal Baseline):**\n   - GT \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0915\u0947 \u092b\u094d\u0930\u0947\u092e\u094d\u0938 \u0915\u094b \u0938\u092e\u092f \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0930\u0948\u0902\u0921\u092e\u093e\u0907\u091c\u093c/\u0936\u092b\u0932 \u0915\u0930\u0928\u093e\u0964 \u092f\u0939 \u091c\u093e\u0902\u091a\u0924\u093e \u0939\u0948 \u0915\u093f TICA \u0914\u0930 \u0911\u091f\u094b\u0915\u094b\u0930\u093f\u0932\u0947\u0936\u0928 \u0915\u0947\u0935\u0932 \u0938\u094d\u091f\u0948\u091f\u093f\u0915 \u091c\u094d\u092f\u094b\u092e\u0947\u091f\u094d\u0930\u0940 \u0938\u0947 \u0928\u0939\u0940\u0902 \u092c\u0932\u094d\u0915\u093f \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0938\u092e\u092f-\u0928\u093f\u0930\u094d\u092d\u0930 \u0915\u093e\u0907\u0928\u0947\u091f\u093f\u0915\u094d\u0938 \u0938\u0947 \u0906 \u0930\u0939\u0947 \u0939\u0948\u0902\u0964\n3. **\u0928\u0947\u0917\u0947\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 2 (Unconditioned / Perturbed Drift Model):**\n   - \u0930\u0948\u0902\u0921\u092e \u0935\u0949\u0915 \u092f\u093e \u0905\u0928\u091f\u094d\u0930\u0947\u0902\u0921 \u0921\u093f\u092b\u094d\u092f\u0942\u091c\u0928/\u091c\u0928\u0930\u0947\u091f\u0930 \u092e\u0949\u0921\u0932\u0964 \u092f\u0939 \u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u0928\u094d\u092f\u0942\u0928\u0924\u092e JSD \u0938\u094d\u0915\u094b\u0930 \u0938\u0902\u092f\u094b\u0917\u0935\u0936 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0924\u093e\u0964\n4. **\u090f\u092c\u094d\u0932\u0947\u0936\u0928 / \u0938\u094d\u091f\u0947\u092c\u093f\u0932\u093f\u091f\u0940 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 (Rollout Length vs Drift):**\n   - \u092e\u0949\u0921\u0932 \u0915\u0940 1-\u0938\u094d\u091f\u0947\u092a, 10-\u0938\u094d\u091f\u0947\u092a, 100-\u0938\u094d\u091f\u0947\u092a \u0914\u0930 1000-\u0938\u094d\u091f\u0947\u092a \u0911\u091f\u094b\u0930\u093f\u0917\u094d\u0930\u0947\u0938\u093f\u0935 \u092a\u094d\u0930\u093f\u0921\u093f\u0915\u094d\u0936\u0928\u094d\u0938 \u092e\u0947\u0902 \u090f\u0930\u0930 \u090f\u0915\u094d\u092f\u0942\u092e\u0941\u0932\u0947\u0936\u0928 (drift) \u0915\u093e \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923\u0964\n\n---\n\n### 6. \u0935\u094d\u092f\u0935\u0939\u093e\u0930\u094d\u092f\u0924\u093e \u090f\u0935\u0902 \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u091a\u0947\u0915 (Feasibility Checks)\n\n- **\u091f\u0942\u0932\u093f\u0902\u0917:** \n  - \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938 \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937\u0923 \u0939\u0947\u0924\u0941 `MDAnalysis` \u0914\u0930 `MDTraj`\u0964\n  - TICA, \u0915\u094d\u0932\u0938\u094d\u091f\u0930\u093f\u0902\u0917 \u0914\u0930 \u0915\u093e\u0907\u0928\u0947\u091f\u093f\u0915 \u090f\u0928\u093e\u0932\u093f\u0938\u093f\u0938 \u0939\u0947\u0924\u0941 `deeptime` \u0914\u0930 `PyEMMA`\u0964\n  - \u0938\u094d\u091f\u0948\u091f\u093f\u0938\u094d\u091f\u093f\u0915\u0932 \u0921\u093e\u092f\u0935\u0930\u094d\u091c\u0947\u0902\u0938 \u0914\u0930 \u0935\u093e\u0938\u0930\u0938\u094d\u091f\u0940\u0928 \u0926\u0942\u0930\u0940 \u0939\u0947\u0924\u0941 `scipy.spatial.distance` \u0914\u0930 `POT` (Python Optimal Transport)\u0964\n- **\u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0915\u0938\u094c\u091f\u0940 (Success Criteria):**\n  - **\u0938\u092e\u093e\u0928\u0924\u093e \u0938\u093f\u0926\u094d\u0927 \u0939\u094b\u0917\u0940 \u092f\u0926\u093f:** \n    1. \u092c\u0948\u0915\u092c\u094b\u0928 \u0935 \u0938\u093e\u0907\u0921\u091a\u0947\u0928 JSD \u0915\u093e \u092e\u093e\u0928 \u092a\u0949\u091c\u093f\u091f\u093f\u0935 \u0915\u0902\u091f\u094d\u0930\u094b\u0932 \u0938\u0940\u092e\u093e \u0915\u0947 1.5x - 2.0x \u0915\u0947 \u092d\u0940\u0924\u0930 \u0930\u0939\u0947\u0964\n    2. TICA 1 \u0914\u0930 TICA 2 \u0938\u094d\u092a\u0947\u0938 \u092e\u0947\u0902 \u092b\u094d\u0930\u0940 \u090f\u0928\u0930\u094d\u091c\u0940 \u092c\u0947\u0938\u093f\u0928\u094b\u0902 \u0915\u093e \u0917\u0941\u0923\u093e\u0924\u094d\u092e\u0915 \u0935 \u092e\u093e\u0924\u094d\u0930\u093e\u0924\u094d\u092e\u0915 \u0938\u0902\u0930\u0947\u0916\u0923 (RMSE < 1.0 $k_B T$) \u0939\u094b\u0964\n    3. \u0915\u094b\u0908 \u0905\u0928\u092b\u093f\u091c\u093f\u0915\u0932 \u0938\u094d\u091f\u0947\u0930\u093f\u0915 \u0915\u094d\u0932\u0948\u0936 (VdW \u0913\u0935\u0930\u0932\u0948\u092a < 1.0 \u00c5) \u0928 \u092a\u093e\u092f\u093e \u091c\u093e\u090f\u0964", "evidence": "\u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u0928\u093f\u0930\u0940\u0915\u094d\u0937\u0923 (task.json) \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u092f\u0939 \u090f\u0915 'design-only task' \u0939\u0948 \u091c\u093f\u0938\u092e\u0947\u0902 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0938\u093f\u092e\u0941\u0932\u0947\u0936\u0928 \u0930\u0928 \u092f\u093e \u0930\u093f\u092a\u0949\u091c\u093f\u091f\u0930\u0940 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u0928 \u0906\u0935\u0936\u094d\u092f\u0915 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u092f\u0942\u091c\u0930 \u0926\u094d\u0935\u093e\u0930\u093e \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0940 \u0917\u0908 \u0915\u093f \u0905\u0927\u094d\u092f\u092f\u0928 \u0915\u093e \u0932\u0915\u094d\u0937\u094d\u092f \u0911\u0932-\u090f\u091f\u092e MD-\u0938\u093f\u092e\u094d\u092f\u0941\u0932\u0947\u091f\u0947\u0921 \u091f\u0947\u091f\u094d\u0930\u093e\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921\u094d\u0938 \u0915\u0947 \u092c\u0948\u0915\u092c\u094b\u0928 \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938, \u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u091f\u0949\u0930\u094d\u0936\u0928\u094d\u0938 \u0914\u0930 \u091f\u0949\u092a TICA \u0915\u0902\u092a\u094b\u0928\u0947\u0902\u091f\u094d\u0938 \u0915\u093e \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u0936\u0928\u0932 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0939\u0948\u0964", "stage": "result", "uncertainties": ["\u0938\u0949\u0932\u094d\u0935\u0947\u0902\u091f \u092e\u094b\u0932\u0947\u0915\u094d\u092f\u0942\u0932\u094d\u0938 \u0915\u093e \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 (\u0915\u094d\u092f\u093e \u092e\u0949\u0921\u0932 \u0915\u0947\u0935\u0932 \u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u0939\u0948\u0935\u0940 \u090f\u091f\u092e\u094d\u0938 \u092a\u094d\u0930\u0947\u0921\u093f\u0915\u094d\u091f \u0915\u0930\u0924\u093e \u0939\u0948 \u092f\u093e \u090f\u0915\u094d\u0938\u092a\u094d\u0932\u093f\u0938\u093f\u091f \u0935\u093e\u091f\u0930 \u092d\u0940 \u0936\u093e\u092e\u093f\u0932 \u0939\u0948)\u0964", "\u0935\u093f\u0936\u093f\u0937\u094d\u091f \u091f\u0947\u091f\u094d\u0930\u093e\u092a\u0947\u092a\u094d\u091f\u093e\u0907\u0921 \u0905\u0928\u0941\u0915\u094d\u0930\u092e\u094b\u0902 \u0915\u0940 \u0938\u091f\u0940\u0915 \u0935\u093f\u0935\u093f\u0927\u0924\u093e (\u0915\u094d\u092f\u093e \u0935\u0947 \u0915\u0947\u0935\u0932 \u092a\u0949\u0932\u0940-\u090f\u0932\u0948\u0928\u093f\u0928 \u0935\u0947\u0930\u093f\u090f\u0902\u091f\u094d\u0938 \u0939\u0948\u0902 \u092f\u093e \u090f\u0930\u094b\u092e\u0948\u091f\u093f\u0915/\u091a\u093e\u0930\u094d\u091c\u094d\u0921 \u0938\u093e\u0907\u0921\u091a\u0947\u0928 \u092f\u0941\u0915\u094d\u0924 \u0939\u0948\u0902)\u0964"], "assumptions": ["\u0917\u094d\u0930\u093e\u0909\u0902\u0921-\u091f\u094d\u0930\u0941\u0925 MD \u091f\u094d\u0930\u0947\u091c\u0947\u0915\u094d\u091f\u0930\u0940 \u0911\u0932-\u090f\u091f\u092e \u0938\u094d\u09